'use strict';
const collectionPage=document.createElement('main');collectionPage.hidden=true;collectionPage.innerHTML='<div class="breadcrumb">Рабочее пространство / Сбор данных</div><div class="heading"><div><h1>Сбор контактов</h1><p>Goszakup → участники → карточки организаций → email и телефоны</p></div></div><section class="panel"><div class="section-title"><h2>Goszakup</h2><span id="collector-state" class="badge"></span></div><p>Контакты добавляются в группу «Бизнес». Запуск не отправляет письма и не подтверждает существование ящиков.</p><div class="actions"><label style="margin:0">Период итогов, дней<input id="collector-days" type="number" min="1" max="365" value="7" style="width:120px"></label><button id="collector-start" class="outline">Включить сбор</button><button id="collector-pause" class="outline">Приостановить</button><button id="collector-retry" class="outline">Повторить ошибки</button><button id="collector-refresh" class="outline">Обновить</button></div><p id="collector-worker" class="rule-text"></p><p id="collector-error" role="status"></p><p id="collector-progress" class="muted"></p></section><div id="collector-counts" class="stats"></div><p class="muted">Данные сохраняются в БД. После сбоя обработка продолжается с сохранённого места. Следующий обход завершённого периода — через 6 часов. Обновите таблицу клиентов, чтобы увидеть новые контакты.</p>';document.body.append(collectionPage);
const collectionButton=[...document.querySelectorAll('aside nav button')].find(b=>b.textContent.includes('Сбор данных'));collectionButton.disabled=false;const oldShowPage=showPage;showPage=function(audiences){collectionPage.hidden=true;collectionButton.classList.remove('active');collectionButton.removeAttribute('aria-current');oldShowPage(audiences);};collectionButton.onclick=()=>{mainPage.hidden=true;audiencePage.hidden=true;collectionPage.hidden=false;for(const button of [clientsButton,audiencesButton]){button.classList.remove('active');button.removeAttribute('aria-current');}collectionButton.classList.add('active');collectionButton.setAttribute('aria-current','page');document.title='Сбор контактов — Рассылки';refreshCollection();};
let collectionStatus=null,collectionUpdating=false;
async function refreshCollection(){if(collectionUpdating)return;collectionUpdating=true;try{const value=await api('/api/collection');collectionStatus=value;document.getElementById('collector-state').textContent=value.enabled?'Сбор включён':'Приостановлен';document.getElementById('collector-state').className='badge '+(value.enabled?'green':'');const days=document.getElementById('collector-days');if(document.activeElement!==days)days.value=value.lookback_days;days.disabled=value.enabled||value.busy;document.getElementById('collector-start').disabled=value.enabled;document.getElementById('collector-pause').disabled=!value.enabled;document.getElementById('collector-worker').textContent=value.worker_alive?(value.busy?'Фоновый обработчик работает. Текущий шаг выполняется.':'Фоновый обработчик доступен.'):'Фоновый обработчик не отвечает. Запустите collect_contacts на сервере; включение само по себе не запускает процесс.';document.getElementById('collector-error').textContent=value.error;document.getElementById('collector-progress').textContent='Окон периода осталось: '+value.windows_left+(value.completed_at?' · Последний обход: '+new Date(value.completed_at).toLocaleString('ru-RU'):'');const container=document.getElementById('collector-counts');container.replaceChildren();const labels={processed:'Обработано источников',queued:'Ожидают обработки',review:'Требуют проверки',companies:'Участников найдено',contacts:'Контактов в базе',emails:'Уникальных email',phones:'Уникальных телефонов'};for(const [key,title] of Object.entries(labels)){const article=document.createElement('article');const span=document.createElement('span');span.textContent=title;const strong=document.createElement('strong');strong.textContent=value.counts[key];article.append(span,strong);container.append(article);}}catch(error){document.getElementById('collector-error').textContent=error.message;}finally{collectionUpdating=false;}}
async function collectionAction(action){const buttons=['collector-start','collector-pause','collector-retry'];buttons.forEach(id=>document.getElementById(id).disabled=true);const payload={action};const days=Number(document.getElementById('collector-days').value);if(action==='start'&&days!==collectionStatus?.lookback_days)payload.days=days;try{await api('/api/collection',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await refreshCollection();}catch(error){document.getElementById('collector-error').textContent=error.message;buttons.forEach(id=>document.getElementById(id).disabled=false);}}
document.getElementById('collector-start').onclick=()=>collectionAction('start');document.getElementById('collector-pause').onclick=()=>collectionAction('pause');document.getElementById('collector-retry').onclick=()=>collectionAction('retry');document.getElementById('collector-refresh').onclick=refreshCollection;setInterval(()=>{if(!collectionPage.hidden)refreshCollection();},5000);
